[51, 'PUC-MG 2024', 'Dadas as entalpias de formação: CO₂(g) = -394 kJ/mol; H₂O(l) = -286 kJ/mol; CH₄(g) = -75 kJ/mol. Qual o ΔH da combustão completa do metano? CH₄ + 2 O₂ → CO₂ + 2 H₂O', '-891 kJ/mol', '-605 kJ/mol', '-966 kJ/mol', '-816 kJ/mol', '-740 kJ/mol', 'a', 'ΔH = ΣHprodutos - ΣHreagentes. ΔH = [1*(-394) + 2*(-286)] - [1*(-75) + 0] = [-394 - 572] + 75 = -966 + 75 = -891 kJ/mol.', 'médio', 0],
