// [135] Tabela Periódica e Propriedades
[135, 'UFPR 2023', 'Qual dos elementos a seguir é classificado como halogênio?', 'Oxigênio (O)', 'Enxofre (S)', 'Bromo (Br)', 'Criptônio (Kr)', 'Cálcio (Ca)', 'c', 'Os halogênios pertencem ao grupo 17 (VIIA) da tabela periódica, que inclui F, Cl, Br, I e At.', 'fácil', 0],
[135, 'UFMG 2024', 'A afinidade eletrônica é a energia liberada quando um átomo neutro e isolado ganha um elétron. Em um mesmo período, ela geralmente:', 'Aumenta da esquerda para a direita.', 'Diminui da esquerda para a direita.', 'Permanece constante.', 'Aumenta de cima para baixo.', 'Diminui de baixo para cima.', 'a', 'No mesmo período, da esquerda para a direita, o raio atômico diminui e a carga nuclear efetiva aumenta. Isso faz com que a atração pelo elétron recebido seja maior, aumentando a afinidade eletrônica.', 'médio', 0],
[135, 'UERJ 2023', 'O íon O²⁻ e o íon Mg²⁺ são isoeletrônicos. Qual deles apresenta o menor raio iônico?', 'O²⁻, pois tem mais prótons.', 'Mg²⁺, pois tem maior número atômico (Z).', 'O²⁻, pois ganhou elétrons.', 'Mg²⁺, pois pertence ao grupo 2.', 'Eles possuem o mesmo raio.', 'b', 'Ambos têm 10 elétrons. O Mg²⁺ tem 12 prótons atraindo esses elétrons, enquanto o O²⁻ tem 8 prótons. Maior atração nuclear encolhe mais a nuvem, logo Mg²⁺ tem menor raio.', 'difícil', 1],

// [136] Geometria Molecular e Polaridade
[136, 'UFRGS 2024', 'A molécula de amônia (NH₃) tem geometria piramidal. Isso ocorre porque o nitrogênio:', 'Possui dois pares de elétrons livres.', 'Não possui par de elétrons livres.', 'Possui um par de elétrons livres que repulsa as ligações.', 'Faz 4 ligações covalentes simples.', 'Tem hibridização sp.', 'c', 'O N tem 5 elétrons na valência, usa 3 para ligar com os H e sobra 1 par livre. A repulsão (Teoria VSEPR) desse par empurra as ligações para baixo, formando a pirâmide.', 'fácil', 0],
[136, 'UEL 2023', 'A molécula CCl₄ (tetracloreto de carbono) apresenta:', 'Geometria tetraédrica e é polar.', 'Geometria quadrada plana e é apolar.', 'Geometria tetraédrica e é apolar.', 'Geometria piramidal e é apolar.', 'Geometria tetraédrica e alta solubilidade em água.', 'c', 'O carbono forma 4 ligações idênticas em geometria tetraédrica regular. Os quatro momentos de dipolo individuais (C-Cl) se anulam, tornando a molécula globalmente apolar.', 'médio', 0],
[136, 'UEM 2024', 'Considerando as moléculas H₂O, BeH₂ e BCl₃, as geometrias são, respectivamente:', 'Angular, linear, trigonal plana.', 'Angular, angular, piramidal.', 'Linear, linear, trigonal plana.', 'Linear, angular, piramidal.', 'Angular, linear, piramidal.', 'a', 'H2O tem 2 pares livres no oxigênio (angular). BeH2 não tem pares livres no Be central (linear). BCl3 não tem pares livres no B (trigonal plana).', 'difícil', 1],

// [137] Concentração de Soluções e Molaridade
[137, 'MACKENZIE 2023', 'Uma solução foi preparada dissolvendo-se 5,85 g de NaCl em água suficiente para 200 mL de solução. Qual a concentração em mol/L? (Massa molar NaCl = 58,5 g/mol)', '0,1 mol/L', '0,5 mol/L', '1,0 mol/L', '2,0 mol/L', '0,2 mol/L', 'b', 'n = 5,85 / 58,5 = 0,1 mol. V = 200 mL = 0,2 L. M = n/V = 0,1 / 0,2 = 0,5 mol/L.', 'fácil', 0],
[137, 'PUC-MG 2024', 'Qual o título em massa (ou porcentagem em massa) de uma solução preparada com 20 g de soluto e 80 g de solvente?', '25%', '20%', '80%', '10%', '30%', 'b', 'A massa total da solução é 20 + 80 = 100 g. O título é a massa do soluto sobre a total: 20/100 = 0,2, o que equivale a 20%.', 'fácil', 0],
[137, 'ITA 2023', 'Uma solução aquosa de ácido nítrico (HNO₃) tem densidade de 1,2 g/mL e concentração em massa (título) de 31,5%. Qual a molaridade da solução? (Massa molar HNO₃ = 63 g/mol)', '12,0 mol/L', '3,15 mol/L', '6,0 mol/L', '4,5 mol/L', '9,0 mol/L', 'c', '1 L = 1000 mL. Massa de 1 L de solução = 1000 * 1,2 = 1200 g. Massa de soluto em 1 L = 0,315 * 1200 = 378 g. Molaridade = m / (M * V) = 378 / (63 * 1) = 6,0 mol/L.', 'difícil', 1],

// [138] Cálculo Estequiométrico
[138, 'FATEC 2024', 'Quantos gramas de oxigênio (O₂, M=32 g/mol) são consumidos para queimar completamente 24 g de carbono puro (C, M=12 g/mol)? (Reação: C + O₂ → CO₂)', '32 g', '64 g', '16 g', '48 g', '96 g', 'b', '24 g de C = 2 mols. A proporção é 1:1, logo precisamos de 2 mols de O2. Massa = 2 * 32g/mol = 64 g.', 'fácil', 0],
[138, 'SENAI 2023', 'Seja a reação: 2 H₂ + O₂ → 2 H₂O. Ao reagir 4 g de hidrogênio (M=2 g/mol) com 16 g de oxigênio (M=32 g/mol), a massa de água (M=18 g/mol) formada será de:', '36 g', '18 g', '54 g', '20 g', '24 g', 'b', 'H2 (4g) = 2 mol. O2 (16g) = 0,5 mol. A proporção requer 2 mols de H2 para 1 mol de O2. Como só temos 0,5 mol de O2, o O2 é o limitante. Produção de H2O = 2 * 0,5 = 1 mol = 18 g.', 'médio', 0],
[138, 'IF-SP 2024', 'Um minério contém 80% de pureza em Fe₂O₃ (M=160 g/mol). Na reação de redução (Fe₂O₃ + 3 CO → 2 Fe + 3 CO₂), que massa de ferro (M=56 g/mol) será obtida a partir de 200 g do minério?', '112 g', '140 g', '89,6 g', '56 g', '224 g', 'a', 'Massa de Fe2O3 puro = 0,8 * 200 = 160 g = 1 mol. 1 mol de Fe2O3 produz 2 mols de Fe. Massa de Fe = 2 * 56 = 112 g.', 'difícil', 1],

